import{norm,unit,keyOf}from'./core.js';
const xml=s=>{const d=new DOMParser().parseFromString(s,'application/xml');if(d.querySelector('parsererror'))throw Error('Tệp XML bị lỗi.');return d;};
const nodes=(x,n)=>[...x.getElementsByTagNameNS('*',n)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function download(data,name,type){const b=data instanceof Blob?data:new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),30000);}
export async function readXlsx(buffer,filename){const zip=await JSZip.loadAsync(buffer);if(!zip.file('xl/workbook.xml'))throw Error(filename+': không phải file XLSX.');let strings=[];if(zip.file('xl/sharedStrings.xml'))strings=nodes(xml(await zip.file('xl/sharedStrings.xml').async('string')),'si').map(si=>nodes(si,'t').map(t=>t.textContent).join(''));const sheets=Object.keys(zip.files).filter(p=>/^xl\/worksheets\/sheet\d+\.xml$/.test(p));let found=null;
 for(const path of sheets){const doc=xml(await zip.file(path).async('string'));const table=nodes(doc,'row').map(row=>{let a=[];for(const c of nodes(row,'c')){const ref=c.getAttribute('r')||'A1';const letters=ref.replace(/\d/g,'');let i=0;for(const ch of letters)i=i*26+ch.charCodeAt(0)-64;i--;const v=nodes(c,'v')[0]?.textContent||'';a[i]=c.getAttribute('t')==='s'?strings[Number(v)]??'':c.getAttribute('t')==='inlineStr'?nodes(c,'t').map(t=>t.textContent).join(''):v;}return a;});const hi=table.findIndex(a=>norm(a[1])==='HỌ VÀ TÊN'&&norm(a[2])==='ĐƠN VỊ'&&norm(a[5])==='TRẠNG THÁI'&&norm(a[6])==='ĐIỂM');if(hi>=0){found=table.slice(hi+1);break;}}
 if(!found)throw Error(filename+': cần form STT, Họ và tên, Đơn vị, Đối tượng, Thời gian nộp bài, Trạng thái, Điểm.');const records=[];for(const [i,r]of found.entries()){if(!r.some(x=>String(x??'').trim()))continue;const status=String(r[5]??'').trim();if(!['Đạt','Không đạt'].includes(status))throw Error(`${filename}: dòng ${i+2} có trạng thái không hợp lệ “${status}”.`);if(!r[2])throw Error(`${filename}: dòng ${i+2} thiếu đơn vị.`);records.push({name:String(r[1]??'').trim(),branch:unit(r[2]),audience:String(r[3]??''),submitted:String(r[4]??''),status,score:String(r[6]??'')});}if(!records.length)throw Error(filename+': không có kết quả.');return{name:filename.replace(/\.xlsx$/i,''),filename,records,errors:{},approved:false};}
export async function readContestFiles(files){const out=[];for(const f of files){if(f.size>100*1024*1024)throw Error('Tệp vượt giới hạn 100 MB.');if(/\.zip$/i.test(f.name)){const z=await JSZip.loadAsync(f);const entries=Object.values(z.files).filter(x=>!x.dir&&/\.xlsx$/i.test(x.name)&&!x.name.includes('__MACOSX'));if(!entries.length)throw Error('ZIP không chứa báo cáo XLSX.');if(entries.length>30)throw Error('Mỗi lần nhập tối đa 30 báo cáo.');for(const e of entries)out.push(await readXlsx(await e.async('arraybuffer'),e.name.split('/').pop()));}else if(/\.xlsx$/i.test(f.name))out.push(await readXlsx(await f.arrayBuffer(),f.name));else throw Error('Chỉ nhận tệp .xlsx hoặc .zip.');}return out;}
export async function readRoster(file){if(file.size>100*1024*1024)throw Error('ZIP quá 100 MB.');const entries=/\.html?$/i.test(file.name)?[{name:file.name,async:()=>file.text()}]:Object.values((await JSZip.loadAsync(file)).files).filter(x=>!x.dir&&/\.html?$/i.test(x.name));const map=new Map(),branches=new Map(),warnings=[];let unnamed=0,duplicate=0;for(const e of entries){const branch=unit(e.name.split('/').pop().replace(/\.html?$/i,''));const ym=branch.match(/(2[3-6])/);if(!ym)continue;const year='20'+ym[1];const doc=new DOMParser().parseFromString(await e.async('string'),'text/html');const displayed=doc.body.textContent.replace(/\s+/g,' ').match(/Chi đoàn\s+(ĐH[A-Z0-9]+)\s*\(\d+\s*đoàn viên\)/);if(displayed&&displayed[1]!==branch){const issue='Tên file '+branch+'.html không khớp nội dung '+displayed[1]+'. File này đã bị bỏ qua; hãy lưu lại đúng chi đoàn.';if(/\.html?$/i.test(file.name))throw Error(issue);warnings.push({branch,issue,severity:'warning'});continue;}branches.set(branch,{name:branch,year});const data=new Map([...doc.querySelectorAll('tr[id^="data-"]')].map(r=>[r.id.slice(5),r]));for(const r of doc.querySelectorAll('tr[id^="hoten-"]')){const name=r.querySelector('div.truncate[title]')?.getAttribute('title')?.trim();if(!name){if(/^\d+$/.test(r.children[1]?.textContent.trim()||''))unnamed++;continue;}const cells=data.get(r.id.slice(6))?.children||[];const v=i=>cells[i]?.textContent.replace(/\s+/g,' ').trim()||'';const key=keyOf(name,branch);const m={key,name,branch,year,ids:v(0)?[v(0)]:[],dob:v(2)||v(3),gender:v(2)?'Nam':v(3)?'Nữ':'',email:v(27),phone:v(28),role:v(25)};if(map.has(key)){duplicate++;map.get(key).ids=[...new Set([...map.get(key).ids,...m.ids])];}else map.set(key,m);}}if(!map.size)throw Error('Không tìm thấy danh sách YUM hợp lệ trong ZIP.');return{members:[...map.values()],branches:[...branches.values()],unnamed,duplicate,warnings};}
const col=i=>{let r='';for(i++;i;i=Math.floor((i-1)/26))r=String.fromCharCode(65+(i-1)%26)+r;return r;};
export async function exportXlsx(title,headers,rows,summaryRows=[]){const z=new JSZip();const now=new Date().toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'});const makeSheet=(hs,rs)=>{const width=hs.length;const cells=[...[[title],[`Thời gian xuất: ${now} • Số lượng: ${rs.length}`],[],hs],...rs];const data=cells.map((r,ri)=>`<row r="${ri+1}" ht="${ri===0?30:ri===3?32:22}" customHeight="1">${r.map((v,ci)=>`<c r="${col(ci)}${ri+1}" s="${ri===0?1:ri===1?2:ri===3?3:4}" t="inlineStr"><is><t xml:space="preserve">${escape(v)}</t></is></c>`).join('')}</row>`).join('');return`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="4" topLeftCell="A5" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${hs.map((h,i)=>`<col min="${i+1}" max="${i+1}" width="${/Họ|Tên/.test(h)?32:/Chi đoàn|Trạng thái|Khóa/.test(h)?20:/Lý do|Ghi chú|Thời gian/.test(h)?32:18}" customWidth="1"/>`).join('')}</cols><sheetData>${data}</sheetData><autoFilter ref="A4:${col(width-1)}${rs.length+4}"/><mergeCells count="2"><mergeCell ref="A1:${col(width-1)}1"/><mergeCell ref="A2:${col(width-1)}2"/></mergeCells><pageMargins left="0.3" right="0.3" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup orientation="landscape" paperSize="9" fitToWidth="1" fitToHeight="0"/></worksheet>`;};
 const sheets=[{name:'Danh sách',data:makeSheet(headers,rows)}];if(summaryRows.length)sheets.push({name:'Tổng hợp chi đoàn',data:makeSheet(['Chi đoàn','Khóa','Tổng','Đã thi','Đạt','Chưa đạt','Chưa thi','Bị lỗi'],summaryRows)});
 z.file('[Content_Types].xml',`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`);z.file('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');z.file('xl/workbook.xml',`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((s,i)=>`<sheet name="${s.name}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`);z.file('xl/_rels/workbook.xml.rels',`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((s,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="styles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`);
 z.file('xl/styles.xml',`<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="3"><font><sz val="12"/><name val="Times New Roman"/></font><font><b/><sz val="16"/><name val="Times New Roman"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="12"/><name val="Times New Roman"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF153B69"/></patternFill></fill></fills><borders count="2"><border/><border><left style="thin"/><right style="thin"/><top style="thin"/><bottom style="thin"/></border></borders><cellStyleXfs count="1"><xf fontId="0" fillId="0" borderId="0" numFmtId="0"/></cellStyleXfs><cellXfs count="5"><xf fontId="0" fillId="0" borderId="0" numFmtId="0" xfId="0"/><xf fontId="1" fillId="0" borderId="0" numFmtId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf fontId="0" fillId="0" borderId="0" numFmtId="0" xfId="0"/><xf fontId="2" fillId="2" borderId="1" numFmtId="0" xfId="0" applyAlignment="1"><alignment wrapText="1" vertical="center"/></xf><xf fontId="0" fillId="0" borderId="1" numFmtId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`);sheets.forEach((s,i)=>z.file(`xl/worksheets/sheet${i+1}.xml`,s.data));return z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
export async function exportErrorsDocx(errors){const resp=await fetch('./error-template.docx');if(!resp.ok)throw Error('Không tải được mẫu Word.');const z=await JSZip.loadAsync(await resp.arrayBuffer());const doc=xml(await z.file('word/document.xml').async('string'));const table=nodes(doc,'tbl')[0];const rs=[...table.children].filter(x=>x.localName==='tr');const template=rs[2].cloneNode(true);rs.slice(2).forEach(r=>r.remove());const ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main';for(const [i,e] of errors.entries()){const m=e.member;const row=template.cloneNode(true);const values=[i+1,m.name,m.ids.join(', '),m.gender==='Nam'?m.dob:'',m.gender!=='Nam'?m.dob:'',m.email,m.phone,e.reason,e.note||m.branch];const cells=[...row.children].filter(x=>x.localName==='tc');cells.forEach((cell,k)=>{const p=nodes(cell,'p')[0];const ts=nodes(cell,'t');if(ts.length){ts[0].textContent=String(values[k]??'');ts.slice(1).forEach(t=>t.textContent='');}else{const r=doc.createElementNS(ns,'w:r');const t=doc.createElementNS(ns,'w:t');t.textContent=String(values[k]??'');r.append(t);p.append(r);}});table.append(row);}z.file('word/document.xml',new XMLSerializer().serializeToString(doc));return z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});}
export async function readErrorDocx(file){const z=await JSZip.loadAsync(file);const f=z.file('word/document.xml');if(!f)throw Error('Không phải tệp Word DOCX hợp lệ.');const d=xml(await f.async('string'));const table=nodes(d,'tbl')[0];if(!table)throw Error('DOCX không có bảng theo mẫu lỗi YUM.');const rows=[...table.children].filter(x=>x.localName==='tr');const entries=[];for(const row of rows.slice(2)){const cells=[...row.children].filter(x=>x.localName==='tc').map(c=>nodes(c,'t').map(t=>t.textContent).join('').trim());if(cells.length<9||!cells[1])continue;const branch=unit(cells[8].match(/ĐH[A-Z0-9]+/i)?.[0]||cells[8]);const year='20'+(branch.match(/(2[3-6])/)?.[1]||'');if(!/^202[3-6]$/.test(year)||!cells[7])throw Error('DOCX có dòng thiếu chi đoàn hoặc trường hợp lỗi.');entries.push({name:cells[1],branch,year,ids:cells[2].split(/[,;]/).map(x=>x.trim()).filter(Boolean),dob:cells[3]||cells[4],gender:cells[3]?'Nam':cells[4]?'Nữ':'',email:cells[5],phone:cells[6],reason:cells[7],note:cells[8]});}if(!entries.length)throw Error('Không có hồ sơ lỗi hợp lệ.');return entries;}
